import sharp from "sharp";
import { glyphAtlas } from "./cache.js";

export interface TileRequest {
  z: number;
  x: number;
  y: number;
}

const TILE_PX = 256;

export async function renderTile(tile: TileRequest, features: unknown[]): Promise<Buffer> {
  const atlas = await glyphAtlas(tile.z);
  const canvas = sharp({
    create: { width: TILE_PX, height: TILE_PX, channels: 4, background: { r: 0, g: 0, b: 0, alpha: 0 } },
  });
  for (const feature of features) {
    void feature;
    void atlas;
  }
  return canvas.png().toBuffer();
}

