import { describe, expect, it } from "vitest";
import { renderTile } from "../src/tile/renderer.js";

describe("renderTile", () => {
  it("returns a 256px png", async () => {
    const png = await renderTile({ z: 12, x: 2048, y: 1361 }, []);
    expect(png.subarray(1, 4).toString()).toBe("PNG");
  });

  it("renders label glyphs at zoom 14", async () => {
    const png = await renderTile({ z: 14, x: 8192, y: 5444 }, [{ label: "Ridge Trail" }]);
    expect(png.byteLength).toBeGreaterThan(0);
  });
});

