import { mkdir, readFile, rename, writeFile } from "node:fs/promises";
import { join } from "node:path";

const CACHE_DIR = process.env.TILE_CACHE_DIR ?? ".tilecache";

export async function glyphAtlas(zoom: number): Promise<Buffer> {
  const path = join(CACHE_DIR, "atlas-" + zoom + ".bin");
  try {
    return await readFile(path);
  } catch {
    return publishAtlas(zoom, path);
  }
}

/**
 * Writes to a per-process temp path and renames into place. A reader either
 * sees the previous atlas or the complete new one, never a half-written file.
 */
async function publishAtlas(zoom: number, path: string): Promise<Buffer> {
  const built = await buildAtlas(zoom);
  await mkdir(CACHE_DIR, { recursive: true });
  const staging = path + "." + process.pid + ".tmp";
  await writeFile(staging, built);
  await rename(staging, path);
  return built;
}

async function buildAtlas(zoom: number): Promise<Buffer> {
  return Buffer.alloc(1024 * (zoom + 1));
}
